mapper.insert:
INSERT INTO tb_unit_price_master (
    company_code
    , sku
    , cust_code
    , unit_price_type
    , start_date
    , unit_price
) VALUES (
    #{companyCode}
  , #{sku}
  , #{custCode}
  , #{unitPriceType}
  , #{startDate}
  , #{unitPrice}
)

INSERT INTO tb_unit_price_history (
	unit_price_seq
    , company_code
    , sku
    , cust_code
    , unit_price_type
    , start_date
    , unit_price
) VALUES (
  unit_price_seq.nextval
  , #{companyCode}
  , #{sku}
  , #{custCode}
  , #{unitPriceType}
  , #{startDate}
  , #{unitPrice}
)

mapper.select:
SELECT count(*) cnt
  FROM tb_unit_price_master
 WHERE company_code = #{companyCode}
   AND sku = #{sku}
   AND cust_code = #{custCode}
   AND unit_price_type = #{unitPriceType}

mapper.update:
UPDATE tb_unit_price_master
   SET unit_price = #{unitPrice}
     , start_date = #{startDate}
     , updated_by = 'ADMIN'
     , update_date = sysdate
 WHERE company_code = #{companyCode}
   AND sku = #{sku}
   AND cust_code = #{custCode}
   AND unit_price_type = #{unitPriceType}
